import csv, yaml
from simulation import run_simulation, compute_metrics

with open('/root/vehicle_params.yaml') as f:
    config=yaml.safe_load(f)

sensor_rows=[]
with open('/root/sensor_data.csv') as f:
    r=csv.DictReader(f)
    for row in r:
        sensor_rows.append(row)

candidates=[]
for kp in [0.22,0.25,0.28,0.3,0.35]:
    for ki in [0.0,0.002,0.005,0.01]:
        for kd in [0.08,0.1,0.12]:
            candidates.append((kp,ki,kd))

best=[]
for kp,ki,kd in candidates:
    tuning={'pid_speed':{'kp':kp,'ki':ki,'kd':kd},'pid_distance':{'kp':0.4,'ki':0.05,'kd':0.02}}
    results=run_simulation(config,tuning,sensor_rows)
    m=compute_metrics(results,config)
    rise=m['rise_time'] or 999
    if rise<10 and m['overshoot_pct']<5 and (m['speed_ss_error'] or 999)<0.5:
        best.append((kp,ki,kd,m['rise_time'],m['overshoot_pct'],m['speed_ss_error']))

print('found',len(best))
print(best[:10])
